#include <iostream>
#include <vector>

using namespace std;

/**
 * Problem: 11192 - Simple Minded Hashing
 * 
 * 解題思路：
 * 1. 這是一個組合問題，可以使用動態規劃 (DP) 解決。
 * 2. 令 dp[i][j][k] 為長度為 i，總和為 j，且最後一個字母的值為 k 的方案數。
 * 3. 限制：字母必須嚴格遞增，且互不相同。
 * 4. 狀態轉移：dp[i][j][k] = sum(dp[i-1][j-k][p]) 其中 p < k。
 * 5. 最大長度 L=26，最大總和 S=351。
 */

long long dp[27][352][27];

int main() {
    // 預處理 DP
    for (int k = 1; k <= 26; ++k) {
        dp[1][k][k] = 1;
    }

    for (int i = 2; i <= 26; ++i) {
        for (int j = 1; j <= 351; ++j) {
            for (int k = 1; k <= 26; ++k) {
                if (j > k) {
                    for (int p = 1; p < k; ++p) {
                        dp[i][j][k] += dp[i - 1][j - k][p];
                    }
                }
            }
        }
    }

    int L, S, caseNum = 1;
    while (cin >> L >> S && (L != 0 || S != 0)) {
        long long total = 0;
        if (L <= 26 && S <= 351) {
            for (int k = 1; k <= 26; ++k) {
                total += dp[L][S][k];
            }
        }
        cout << "Case " << caseNum++ << ": " << total << endl;
    }

    return 0;
}
